"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["87515"],{96726(e){e.exports=JSON.parse('{"id":"V4-178","slug":"european-central-bank","term":"European Central Bank","also_known_as":[],"difficulty":"Beginner","definition":"The European Central Bank (ECB) is the central bank for the countries that use the euro, responsible for monetary policy in the euro area and for supervising its largest banks.","explanation":["The ECB was established in 1998, shortly before the euro was introduced in 1999, and is based in Frankfurt, Germany. Together with the national central banks of euro area countries, it forms the Eurosystem.","The ECB\u2019s primary objective is price stability, which it defines as inflation of 2% over the medium term. It sets key interest rates, including the deposit facility rate, and uses other tools, such as asset purchases and lending to banks.","Monetary policy decisions are made by the Governing Council, made up of the six members of the Executive Board, including the President, and the governors of the national central banks of euro area countries.","Since 2014, the ECB has also directly supervised the largest banks in the euro area through the Single Supervisory Mechanism, while national authorities supervise smaller banks under its oversight.","For example, after inflation rose sharply in 2022, the ECB raised interest rates for the first time in more than a decade. During the euro area debt crisis, its president\u2019s 2012 pledge to do whatever it takes to preserve the euro helped calm markets. The ECB is independent of national governments and EU institutions."],"note":"","total":1725,"prev":{"slug":"eurobond","term":"Eurobond"},"next":{"slug":"european-option","term":"European Option"}}')}}]);